```python
def is_string_dtype(arr_or_dtype) -> bool:
    """
    Check whether the provided array or dtype is of the string dtype.

    Parameters
    ----------
    arr_or_dtype : array-like
        The array or dtype to check.

    Returns
    -------
    boolean
        Whether or not the array or dtype is of the string dtype.

    Examples
    --------
    >>> is_string_dtype(str)
    True
    >>> is_string_dtype(object)
    True
    >>> is_string_dtype(int)
    False
    >>> is_string_dtype(np.array(['a', 'b']))
    True
    >>> is_string_dtype(pd.Series([1, 2]))
    False
    """
    def condition(dtype) -> bool:
        return isinstance(dtype, (np.string_, np.object_)) and not is_excluded_dtype(dtype)

    def is_excluded_dtype(dtype) -> bool:
        is_excluded_checks = (is_categorical_dtype, is_period_dtype, is_interval_dtype)
        return any(check(dtype) for check in is_excluded_checks)

    def is_categorical_dtype(dtype) -> bool:
        return isinstance(dtype, pd.CategoricalDtype)

    def is_period_dtype(dtype) -> bool:
        return isinstance(dtype, pd.PeriodDtype)

    def is_interval_dtype(dtype) -> bool:
        return isinstance(dtype, pd.IntervalDtype)

    return _is_dtype(arr_or_dtype, condition)
